// The render check: the cases of cases.js in the chosen styles and widths, drawn exactly as the save page draws them,
// with automatic checks for what has broken before. It is both /render-check.html and «Проверка картинок» in the settings;
// see RENDER-CHECKS.md.
import React,{useEffect,useRef,useState} from 'react';
import {SchedulePicture} from '../App.jsx';
import {PICTURE_STYLES} from '../services/picture-styles.js';
import {CASES,STYLES,WIDTHS} from './cases.js';

const STYLE_NAMES=Object.fromEntries(PICTURE_STYLES.map(style=>[style.id,style.name]));
const WEEK_WIDTH=1400;
const PUNCTUATION=/^[\s:—–·\-.,]+$/;
const inside=(box,frame,slack=1)=>box.left>=frame.left-slack&&box.right<=frame.right+slack&&box.top>=frame.top-slack&&box.bottom<=frame.bottom+slack;
const overlap=(a,b)=>Math.max(0,Math.min(a.right,b.right)-Math.max(a.left,b.left))*Math.max(0,Math.min(a.bottom,b.bottom)-Math.max(a.top,b.top));
const describe=node=>{const element=node.nodeType===1?node:node.parentElement;return `${element.tagName.toLowerCase()}${element.className&&typeof element.className==='string'?'.'+element.className.trim().split(/\s+/).join('.'):''} «${(node.textContent||'').trim().slice(0,30)}»`;};
const textNodes=root=>{const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:node=>node.textContent.trim()?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT});const list=[];while(walker.nextNode())list.push(walker.currentNode);return list;};
const rects=node=>{const range=document.createRange();range.selectNodeContents(node);return [...range.getClientRects()].filter(box=>box.width>0.5&&box.height>0.5);};
// Boxes count as one line when their middles sit within half a box of each other: glyphs of one line differ by fractions of a pixel.
const lines=list=>{const middles=[];for(const box of list){const middle=(box.top+box.bottom)/2;if(!middles.some(other=>Math.abs(other-middle)<box.height/2))middles.push(middle);}return middles.length;};
// A glyph box is taller than its line, so neighbouring lines touch; only the middle half of each box is compared.
const core=box=>({left:box.left,right:box.right,top:box.top+box.height/4,bottom:box.bottom-box.height/4});

// What has broken before, checked on the drawn picture.
export function checkPicture(sheet){
  const issues=[],frame=sheet.getBoundingClientRect();
  const add=(kind,detail)=>{if(issues.length<12)issues.push(`${kind}: ${detail}`);};
  // 1. Nothing sticks out of the picture, or out of a box that clips it.
  for(const element of sheet.querySelectorAll('*')){
    const box=element.getBoundingClientRect();if(box.width<1||box.height<1)continue;
    if(!inside(box,frame))add('за краем картинки',describe(element));
    let parent=element.parentElement;
    while(parent&&parent!==sheet){const style=getComputedStyle(parent);if(style.overflow!=='visible'){const clip=parent.getBoundingClientRect();if(!inside(box,clip,1.5))add('обрезано',`${describe(element)} в ${describe(parent)}`);break;}parent=parent.parentElement;}
  }
  const texts=textNodes(sheet).map(node=>({node,boxes:rects(node)}));
  for(const {node,boxes} of texts){
    const text=node.textContent.trim(),letters=text.replace(/[\s­]/g,'');
    // 2. Letters stacked in a column: a word squeezed into a strip.
    if(letters.length>=4&&lines(boxes)>=Math.ceil(letters.length*.6))add('буквы столбиком',describe(node));
    // 3. A word torn apart with no hyphen at the break: its first and last letters stand on different lines.
    const letter=index=>{const range=document.createRange();range.setStart(node,index);range.setEnd(node,index+1);return range.getBoundingClientRect();};
    for(const match of node.textContent.matchAll(/[А-Яа-яЁёA-Za-z0-9:]{2,}/g)){
      const first=letter(match.index),last=letter(match.index+match[0].length-1);
      if(Math.abs((first.top+first.bottom)/2-(last.top+last.bottom)/2)>first.height/2)add('слово разорвано без дефиса',`«${match[0]}» в ${describe(node)}`);
    }
    // 4. A colon, dash or dot alone on its line: nothing else of the same event (text or logo) stands beside it,
    // the way a scoreboard puts the colon between two crests.
    if(PUNCTUATION.test(text)&&boxes.length){const own=boxes[0],event=node.parentElement.closest('[data-type],.i-row,.i-witem')||sheet,near=box=>Math.abs((box.top+box.bottom)/2-(own.top+own.bottom)/2)<Math.max(own.height,box.height)/2;
      if(!texts.some(other=>other.node!==node&&event.contains(other.node)&&other.boxes.some(near))&&![...event.querySelectorAll('img')].some(image=>near(image.getBoundingClientRect())))add('знак один на строке',describe(node));}
  }
  // 5. Text over text.
  for(let a=0;a<texts.length;a++)for(let b=a+1;b<texts.length;b++){
    if(texts[a].node.parentElement.contains(texts[b].node)||texts[b].node.parentElement.contains(texts[a].node))continue;
    for(const boxA of texts[a].boxes)for(const boxB of texts[b].boxes)if(overlap(core(boxA),core(boxB))>6){add('текст на тексте',`${describe(texts[a].node)} и ${describe(texts[b].node)}`);break;}
  }
  // 6. A classic event icon stands on the middle of its event, level with the time.
  for(const icon of sheet.querySelectorAll('[data-id=icon-container] svg')){const row=icon.closest('[data-type]');if(!row)continue;const middle=box=>(box.top+box.bottom)/2,shift=middle(icon.getBoundingClientRect())-middle(row.getBoundingClientRect());
    if(Math.abs(shift)>1.5)add('иконка не по центру события',`${describe(row)} на ${Math.round(shift)} px`);}
  // 7. Teams on one line hold their logos on the outer sides; teams one under the other both lead with theirs.
  for(const teams of sheet.querySelectorAll('.i-teams,.i-wteams,.m-game-line-teams')){const [first,second]=teams.children,logo=second?.querySelector('img');if(!first||!logo)continue;
    const stacked=second.getBoundingClientRect().top>=first.getBoundingClientRect().bottom-1;
    const name=[...second.childNodes].find(node=>node!==logo),box=name&&(name.nodeType===1?name.getBoundingClientRect():(()=>{const range=document.createRange();range.selectNodeContents(name);return range.getBoundingClientRect();})());
    if(box&&stacked===(logo.getBoundingClientRect().left>box.left))add('логотип не с той стороны',`${describe(second)} ${stacked?'в столбике':'в строке'}`);}
  // 8. In the iOS styles an event's text, or its teams with their logos, stand level with the time beside it.
  const firstLetter=root=>{const node=textNodes(root)[0];if(!node)return null;const range=document.createRange();range.setStart(node,0);range.setEnd(node,1);return range.getBoundingClientRect();};
  for(const row of sheet.querySelectorAll('.i-row')){const time=row.querySelector(':scope>.i-time'),body=row.querySelector(':scope>.i-body');if(!time||!body)continue;const a=firstLetter(time),b=firstLetter(body);
    if(!a||!b||Math.abs(b.top-a.top)>a.height/2)continue;
    if(Math.abs(b.top-a.top)>0.6)add('текст не на линии времени',`${describe(body)} на ${(b.top-a.top).toFixed(1)} px`);
    const logo=body.querySelector(':scope>.i-teams img');if(logo){const shift=(logo.getBoundingClientRect().top+logo.getBoundingClientRect().bottom)/2-(a.top+a.bottom)/2;if(Math.abs(shift)>1.5)add('логотип не на линии времени',`${describe(body)} на ${Math.round(shift)} px`);}}
  // 9. A one-line iOS row stands in the middle of its height, and its text keeps clear of the colour bar at its left.
  for(const row of sheet.querySelectorAll('.i-row:not(.is-picture):not(.is-text)')){const box=row.getBoundingClientRect(),inner=[...row.children].filter(child=>child.textContent.trim()),letters=inner.map(firstLetter).filter(Boolean);if(!letters.length)continue;
    if(inner.every(child=>lines(rects(textNodes(child)[0]||child))<=1)&&letters.every(letter=>Math.abs(letter.top-letters[0].top)<1)&&box.height<60){const shift=(letters[0].top+letters[0].bottom)/2-(box.top+box.bottom)/2;if(Math.abs(shift)>1.5)add('строка не по центру',`${describe(row)} на ${shift.toFixed(1)} px`);}
    if(row.classList.contains('has-bar')){const bar=parseFloat(getComputedStyle(row,'::after').left)+parseFloat(getComputedStyle(row,'::after').width),gap=Math.min(...letters.map(letter=>letter.left))-box.left-bar;if(gap<8)add('текст у полоски цвета',`${describe(row)}: ${gap.toFixed(1)} px`);}}
  return issues;
}

function Render({entry,style,width,onResult}){
  const ref=useRef(null);
  useEffect(()=>{let stop=false;document.fonts.ready.then(()=>new Promise(resolve=>setTimeout(resolve,60))).then(()=>{if(!stop&&ref.current)onResult(checkPicture(ref.current));});return()=>{stop=true;};},[]);
  return <div className="m-preview-document" ref={ref} style={{width,background:'#fff',position:'relative'}}>
    <SchedulePicture style={style} state={entry.state} languages={entry.languages||['en']} translationMode={entry.translationMode||'block'} textBlocks={{}}/>
  </div>;
}

const widthsOf=entry=>[...WIDTHS,...(entry.state.scheduleMode==='week'?[WEEK_WIDTH]:[])];
// Every run of the chosen case, style and width ('all' takes every one of them).
export function matrixRuns({kase='all',style='all',width='all'}={}){
  return CASES.filter(entry=>kase==='all'||entry.id===kase).flatMap(entry=>STYLES.filter(id=>style==='all'||id===style).flatMap(id=>widthsOf(entry).filter(value=>width==='all'||value===Number(width)).map(value=>({entry,style:id,width:value,key:`${entry.id}|${id}|${value}`}))));
}

const Choice=({label,value,onChange,options})=><label className="m-check-choice"><span>{label}</span><select value={value} onChange={event=>onChange(event.target.value)}>{options.map(([option,name])=><option key={option} value={option}>{name}</option>)}</select></label>;

// The choice comes first; the pictures are drawn and checked only when asked, since every one of them is a full picture.
export default function RenderMatrix({initial={},auto=false}){
  const [choice,setChoice]=useState({kase:'all',style:'all',width:'all',...initial});
  const [shown,setShown]=useState(auto?choice:null),[results,setResults]=useState({});
  const runs=shown?matrixRuns(shown):[];
  const done=runs.filter(run=>results[run.key]).length,failed=runs.filter(run=>results[run.key]?.length);
  useEffect(()=>{window.__renderCheck={total:runs.length,done,failed:Object.fromEntries(failed.map(run=>[run.key,results[run.key]]))};},[done,shown]);
  const set=key=>value=>setChoice(current=>({...current,[key]:value}));
  const planned=matrixRuns(choice).length;
  return <div className="m-render-check">
    <div className="m-check-choices">
      <Choice label="Случай" value={choice.kase} onChange={set('kase')} options={[['all','Все случаи'],...CASES.map(entry=>[entry.id,`${entry.bug?'⚠ ':''}${entry.title}`])]}/>
      <Choice label="Стиль" value={choice.style} onChange={set('style')} options={[['all','Все стили'],...STYLES.map(id=>[id,STYLE_NAMES[id]||id])]}/>
      <Choice label="Ширина" value={choice.width} onChange={set('width')} options={[['all','Все ширины'],...[...WIDTHS,WEEK_WIDTH].map(value=>[String(value),`${value*2} px${value===WEEK_WIDTH?' (только неделя)':''}`])]}/>
      <button type="button" className="m-check-run" disabled={!planned} onClick={()=>{setResults({});setShown({...choice});}}>{planned?`Показать: ${planned} ${planned%10===1&&planned%100!==11?'картинка':planned%10>=2&&planned%10<=4&&(planned%100<10||planned%100>=20)?'картинки':'картинок'}`:'Нет таких картинок'}</button>
    </div>
    {shown&&<>
      <p className={`m-check-summary ${failed.length?'is-bad':done===runs.length?'is-good':''}`}>{done<runs.length?`Проверено ${done} из ${runs.length}…`:failed.length?`С ошибками: ${failed.length} из ${runs.length}`:`Все ${runs.length} без ошибок`}</p>
      {failed.length>0&&<ul className="m-check-issues">{failed.map(run=><li key={run.key}><b>{run.entry.id} · {STYLE_NAMES[run.style]} · {run.width*2} px</b><ul>{results[run.key].map((issue,index)=><li key={index}>{issue}</li>)}</ul></li>)}</ul>}
      {CASES.filter(entry=>runs.some(run=>run.entry===entry)).map(entry=><section key={`${entry.id}|${shown.style}|${shown.width}`} className="m-check-case">
        <h2>{entry.title}</h2><p className="m-check-id">{entry.id}</p>{entry.bug&&<p className="m-check-bug">Было: {entry.bug}</p>}
        <div className="m-check-figures">{runs.filter(run=>run.entry===entry).map(run=><figure key={run.key}>
          <figcaption className={results[run.key]?.length?'is-bad':''}>{STYLE_NAMES[run.style]} · {run.width*2} px{results[run.key]?.length?` · ошибок: ${results[run.key].length}`:''}</figcaption>
          <div className="m-check-frame"><Render entry={run.entry} style={run.style} width={run.width} onResult={issues=>setResults(current=>({...current,[run.key]:issues}))}/></div>
        </figure>)}</div>
      </section>)}
    </>}
  </div>;
}
