// Every combination the finished picture has to survive. render-check.html draws each case in every style and at every
// width, and checks the result (see RENDER-CHECKS.md). A case that once broke keeps a `bug` note saying what broke and when.
// A feature that changes what a schedule can hold, or a new style, adds its cases here before it is released.
import {FNL_TEAMS} from '../services/fnl-teams.js';
import {ICON_LABELS,EVENT_COLORS,RETIRED_ICONS} from '../services/editor.js';

const svg=(width,height,fill,label)=>`data:image/svg+xml;utf8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><rect width="${width}" height="${height}" rx="${Math.min(width,height)/8}" fill="${fill}"/><text x="50%" y="55%" font-family="Arial" font-size="${Math.min(width,height)/4}" text-anchor="middle" fill="#fff">${label}</text></svg>`)}`;
export const PICTURES={wide:svg(800,300,'#3f6fb5','wide'),tall:svg(300,800,'#b53f6f','tall'),square:svg(400,400,'#3fa06a','sq'),logo:svg(120,120,'#c23b22','A')};
const team=(index)=>({name:FNL_TEAMS[index].name,image:FNL_TEAMS[index].image});
const longTeam={name:'Красные Крылья Самарской области',image:null};
const tr=(en,es,de)=>({en,...(es?{es}:{}),...(de?{de}:{})});
let next=0;const id=()=>`c${++next}`;
const items=list=>list.map(item=>({id:id(),...item}));
// A row id makes consecutive items one group, standing side by side.
const group=(list)=>{const row=`row-${++next}`;return list.map(item=>({id:id(),row,...item}));};
const title=(text='Расписание на день')=>({type:'h1',description:text,translations:tr('Daily schedule','Horario del día','Tagesplan')});
const date=(extra={})=>({type:'date',date:'2026-10-27',description:'',...extra});
const breakfast={type:'timed',time:'08:30',icon:'utensils',color:'orange',description:'Завтрак',translations:tr('Breakfast','Desayuno','Frühstück')};
const training={type:'range',time:'10:00',endTime:'11:30',icon:'football-field',color:'green',description:'Тренировка на основном поле',translations:tr('Training on the main pitch','Entrenamiento en el campo principal','Training auf dem Hauptplatz')};
const lunch={type:'timed',time:'13:00',icon:'utensils',description:'Обед',translations:tr('Lunch','Almuerzo','Mittagessen')};
const bus={type:'untimed',icon:'bus',description:'Выезд на стадион',translations:tr('Departure to the stadium')};
const game=(extra={})=>({type:'game',time:'19:00',endTime:'21:00',icon:'soccer-ball',color:'red',homeTeam:team(0),awayTeam:team(1),description:'Стадион «Арсенал»',translations:tr('Arsenal stadium'),...extra});
const picture=(kind,extra={})=>({type:'image',image:PICTURES[kind],fit:'contain',...extra});

const DAY=[
  {id:'day-basic',title:'Обычный день: заголовок, дата, все виды событий',items:items([title(),date({description:'Москва'}),breakfast,training,lunch,bus,{type:'h3',description:'Вечер'},game(),{type:'comment',description:'Форма — домашняя, красная'},{type:'timed',time:'22:30',icon:'bed',color:'purple',description:'Отбой'}])},
  {id:'day-plain',title:'Без иконок, цветов и времени',items:items([{type:'untimed',description:'Собрание'},{type:'untimed',description:'Разбор'},{type:'untimed',description:''}])},
  {id:'day-no-icons-colors',title:'Время есть, иконок нет, у части событий цвет',bug:'0.28.0: пустая плитка рисовалась на месте невыбранной иконки',items:items([{type:'timed',time:'09:00',color:'blue',description:'Зарядка'},{type:'timed',time:'09:30',description:'Завтрак'},{type:'range',time:'10:00',endTime:'12:00',color:'green',description:'Тренировка'}])},
  {id:'day-long-words',title:'Длинные слова и очень длинный заголовок',bug:'0.28.0: заголовок рвался посреди слова без дефиса',items:items([title('Восстановительно-профилактические мероприятия'),{type:'timed',time:'10:00',icon:'medical',description:'Физиотерапевтическиепроцедурыбезпробелов и углублённое медицинское обследование'},{type:'untimed',icon:'video',description:'Видеоразбор'}])},
  {id:'day-group-two',title:'Группа из двух событий',items:[...items([title()]),...group([breakfast,lunch]),...items([bus])]},
  {id:'day-group-game-empty-picture',title:'Группа: матч + пустое событие + картинка с фоном',bug:'0.28.1: матч сжимался в столбик, «:» оставалось одно на строке; фон картинки при «Вписать» не был виден',items:group([{...game(),description:'',icon:null,color:undefined,time:'11:00',endTime:'12:00'},{type:'untimed',description:''},picture('wide',{background:'orange'})])},
  {id:'day-group-title-logo',title:'Заголовок и логотип рядом (группа)',items:[...group([title(),picture('logo')]),...items([breakfast,training])]},
  {id:'day-group-pictures',title:'Две картинки рядом',items:group([picture('tall',{background:'blue'}),picture('wide',{fit:'cover'})])},
  {id:'day-group-four',title:'Группа из четырёх событий с длинными текстами',items:group([training,{...breakfast,description:'Завтрак в ресторане гостиницы на первом этаже'},bus,{...lunch,description:'Обед'}])},
  {id:'day-group-games',title:'Два матча рядом, длинные названия команд',items:group([game({awayTeam:longTeam}),game({homeTeam:team(2),awayTeam:team(3),description:''})])},
  {id:'day-group-mixed',title:'В группе комментарий, подзаголовок и событие',items:group([{type:'comment',description:'Комментарий к тренировке'},{type:'h2',description:'Подзаголовок'},training])},
  {id:'day-pictures',title:'Картинки отдельно: все способы вставки и фоны',bug:'0.28.1: фон при «Вписать» не был виден',items:items([picture('wide',{fit:'contain',background:'orange'}),picture('tall',{fit:'contain',background:'blue'}),picture('square',{fit:'cover'}),picture('wide',{fit:'fill'}),picture('logo',{fit:'none',background:'gray'})])},
  {id:'day-picture-first',title:'Картинка первой строкой без заголовка',bug:'0.28.0: картинка уходила в угол шапки',items:items([picture('wide'),breakfast])},
  {id:'day-dates',title:'Даты: диапазон, несколько дат, подписи',items:items([date({endDate:'2026-10-30',description:'Сборы'}),breakfast,date({date:'2026-10-28',description:'Второй день'}),lunch])},
  {id:'day-headings',title:'Заголовки и комментарии подряд',items:items([title(),{type:'h2',description:'Утро'},{type:'h3',description:'Зал'},{type:'comment',description:'Взять форму'},{type:'comment',description:'И воду'},breakfast])},
  {id:'day-inline',title:'Перевод «В строке», три языка',translationMode:'inline',languages:['en','es','de'],items:items([title(),breakfast,training,game()])},
  {id:'day-text-block',title:'Перевод «Отдельно», два языка',translationMode:'text-block',languages:['en','es'],items:items([title(),breakfast,training,lunch])},
  {id:'day-empty-times',title:'Время стёрто прочерком: у события, у конца интервала, у матча',items:items([{type:'timed',time:'',icon:'utensils',description:'Завтрак'},{type:'range',time:'10:00',endTime:'',icon:'football-field',description:'Тренировка'},{type:'range',time:'',endTime:'',description:'Без времени совсем'},game({time:'',endTime:''})])},
  {id:'day-all-icons',title:'Все иконки, каждая со своей подписью: единый стиль, без повторов',items:items(Object.entries(ICON_LABELS).filter(([icon])=>!RETIRED_ICONS.includes(icon)).map(([icon,label],index)=>({type:'timed',time:`${String(6+Math.floor(index/4)).padStart(2,'0')}:${String(index%4*15).padStart(2,'0')}`,icon,color:index%5?undefined:'green',description:label})))},
  {id:'day-colors',title:'Все цвета: с иконкой (плитка) и без неё (полоска)',items:items(Object.entries(EVENT_COLORS).flatMap(([color,[label]],index)=>[{type:'timed',time:`${String(8+index).padStart(2,'0')}:00`,icon:'bus',color,description:label},{type:'timed',time:`${String(8+index).padStart(2,'0')}:30`,color,description:`${label} без иконки`}]))},
  {id:'day-squares',title:'Картинка квадратом: слева, по центру, справа, рядом с обычными событиями',items:items([title(),picture('logo',{size:'left',background:'gray'}),breakfast,picture('wide',{size:'center',fit:'cover'}),training,picture('tall',{size:'right',background:'blue'}),picture('wide',{size:'full'})])},
  {id:'day-group-squares',title:'Квадрат в группе: рядом с событием, с матчем, с длинным текстом',items:[...items([title()]),...group([picture('logo',{size:'left',background:'gray'}),training]),...group([game(),picture('square',{size:'right',fit:'cover'})]),...group([picture('tall',{size:'center',background:'orange'}),{...breakfast,description:'Завтрак в ресторане гостиницы на первом этаже, потом сбор в холле'}])]},
  {id:'day-heading-icons',title:'Заголовки с иконкой, матч с иконкой без подписи, события без текста',bug:'0.28.5: иконка заголовка в iOS не рисовалась; в строке логотипы обеих команд стояли слева от названий; «09:00–10:00» без пробелов; под матчем без подписи оставался английский перевод стёртой подписи',items:items([{...game({homeTeam:team(3),awayTeam:team(5),description:'',icon:'football-field',color:undefined}),time:'09:00',endTime:'10:00'},{type:'timed',time:'09:30',icon:'football-field',description:''},{type:'h1',icon:'trophy',description:'Финал кубка'},{type:'h2',icon:'football-field',description:'Тренировка'},{type:'h3',icon:'bus',description:'Выезд'},{type:'comment',icon:'important',description:'Взять паспорт'},{type:'timed',time:'11:30',icon:'football-field',description:''}])},
  {id:'day-empty',title:'Пустое расписание',items:[]},
];

const WEEK_START='2026-10-26',WEEK_END='2026-11-01';
const day=(key,list)=>list.map(item=>({id:id(),dayKey:key,...item}));
const dayGroup=(key,list)=>{const row=`row-${++next}`;return list.map(item=>({id:id(),dayKey:key,row,...item}));};
const WEEK=[
  {id:'week-basic',title:'Обычная неделя: выходные, группа, матч, картинка',state:{offDays:{'2026-10-28':true},schedule:[
    ...day('2026-10-26',[breakfast,training,lunch]),...dayGroup('2026-10-27',[training,bus]),...day('2026-10-28',[{type:'untimed',icon:'bed',description:'Отдых'}]),
    ...day('2026-10-30',[{type:'timed',time:'16:00',icon:'bus',color:'gray',description:'Выезд'},{type:'comment',description:'Форма выездная'}]),...day('2026-10-31',[game()]),...day('2026-11-01',[picture('wide',{background:'orange'})])]}},
  {id:'week-crowded',title:'Перегруженный день и длинные слова',bug:'0.28.0: заголовок налезал на дни недели при ширине «по тексту»',state:{cardTitle:'Расписание на неделю',offDays:{},schedule:[
    ...day('2026-10-26',Array.from({length:12},(_,index)=>({type:'timed',time:`${String(8+index).padStart(2,'0')}:00`,icon:index%2?'utensils':'football-field',color:index%3?undefined:'blue',description:index%4?'Тренировка':'Восстановительные мероприятия'}))),
    ...day('2026-10-29',[game({awayTeam:longTeam}),{type:'untimed',description:'Физиотерапевтическиепроцедурыбезпробелов'}])]}},
  {id:'week-groups',title:'Группы в неделе: матч + картинка, три события',state:{offDays:{'2026-10-27':true},schedule:[...dayGroup('2026-10-27',[game({description:''}),picture('square',{background:'yellow'})]),...dayGroup('2026-10-29',[breakfast,lunch,bus])]}},
  {id:'week-empty',title:'Пустая неделя, все дни выходные',state:{offDays:Object.fromEntries(['2026-10-26','2026-10-27','2026-10-28','2026-10-29','2026-10-30','2026-10-31','2026-11-01'].map(key=>[key,true])),schedule:[]}},
  {id:'week-squares',title:'Квадраты в неделе: отдельно и в группе',state:{offDays:{},schedule:[...day('2026-10-26',[picture('logo',{size:'left',background:'gray'}),breakfast]),...day('2026-10-27',[picture('square',{size:'center',fit:'cover'})]),...dayGroup('2026-10-28',[picture('logo',{size:'right',background:'yellow'}),training]),...day('2026-10-29',[picture('tall',{size:'right',background:'blue'})])]}},
  {id:'week-midweek',title:'Неделя с середины (пустые клетки до и после)',state:{weekStart:'2026-10-29',weekEnd:'2026-11-04',offDays:{},schedule:[...day('2026-10-29',[breakfast]),...day('2026-11-03',[training])]}},
].map(entry=>({...entry,state:{scheduleMode:'week',weekStart:WEEK_START,weekEnd:WEEK_END,cardTitle:'Неделя команды',...entry.state}}));

export const CASES=[...DAY.map(entry=>({...entry,state:{scheduleMode:'day',schedule:entry.items}})),...WEEK];
export const STYLES=['classic','ios','ios-print'];
// Logical widths (the picture is twice as many pixels): the narrowest the slider allows, two phone-like ones, the default.
export const WIDTHS=[160,260,448,896];
